CREATE POLICY "user view scopes quota reads" ON public.user_ai_quotas AS RESTRICTIVE FOR SELECT TO authenticated USING (NOT (SELECT public.user_view_active()) OR user_id=(SELECT public.effective_user_id()));
CREATE POLICY "user view scopes tier reads" ON public.ai_tiers AS RESTRICTIVE FOR SELECT TO authenticated USING (NOT (SELECT public.user_view_active()) OR EXISTS (SELECT 1 FROM public.user_ai_quotas q WHERE q.user_id=(SELECT public.effective_user_id()) AND q.tier_id=ai_tiers.id) OR (is_default AND NOT EXISTS (SELECT 1 FROM public.user_ai_quotas q WHERE q.user_id=(SELECT public.effective_user_id()))));